import type { ID } from '../types/rpg';
import { http } from './http.api';

/** NPC portraits generated by Fotor through the API (GM only). See the back end's portraits use-cases. */

/** Profile applied to every portrait; the other profiles are per race. */
export const STYLE_PROFILE = 'style';

export interface PortraitProfile {
  key: string;
  prompt: string;
  /** `/files/...` uploads or https URLs, sent as reference images. */
  references: string[];
  updatedAt: string;
}

export interface PortraitDraft {
  profile: string;
  prompt: string;
  references: string[];
}

export type PortraitJobStatus = 'pending' | 'done' | 'failed';

export interface PortraitJob {
  id: number;
  npcId: number;
  taskId: string;
  profile: string | null;
  prompt: string;
  references: string[];
  status: PortraitJobStatus;
  error: string | null;
  imageUrl: string | null;
  createdAt: string;
  finishedAt: string | null;
}

export const PortraitApi = {
  async status(): Promise<{ enabled: boolean }> {
    return (await http.get('/api/gm/portraits/status')).data;
  },

  async profiles(): Promise<PortraitProfile[]> {
    return (await http.get('/api/gm/portrait-profiles')).data;
  },

  async saveProfile(key: string, body: { prompt: string; references: string[] }): Promise<PortraitProfile> {
    return (await http.put(`/api/gm/portrait-profiles/${encodeURIComponent(key)}`, body)).data;
  },

  async deleteProfile(key: string): Promise<void> {
    await http.delete(`/api/gm/portrait-profiles/${encodeURIComponent(key)}`);
  },

  async draft(npcId: ID, profile: string | null): Promise<PortraitDraft> {
    return (await http.get(`/api/gm/npcs/${npcId}/portrait/draft`, { params: profile ? { profile } : {} })).data;
  },

  async jobs(npcId: ID): Promise<PortraitJob[]> {
    return (await http.get(`/api/gm/npcs/${npcId}/portraits`)).data;
  },

  async generate(
    npcId: ID,
    body: { profile: string | null; prompt: string; references: string[] },
  ): Promise<PortraitJob> {
    return (await http.post(`/api/gm/npcs/${npcId}/portraits`, body)).data;
  },

  async check(jobId: number): Promise<PortraitJob> {
    return (await http.post(`/api/gm/portraits/${jobId}/check`)).data;
  },

  async apply(jobId: number): Promise<void> {
    await http.post(`/api/gm/portraits/${jobId}/apply`);
  },

  async remove(jobId: number): Promise<void> {
    await http.delete(`/api/gm/portraits/${jobId}`);
  },

  /** Uploads a reference image; returns its `/files/...` URL. */
  async uploadReference(file: File): Promise<string> {
    const form = new FormData();
    form.append('file', file);
    return (await http.post<{ url: string }>('/api/uploads/image', form)).data.url;
  },
};
